INSERT INTO repo_scrs (scr_id, name, sustainability_dimension, domain, definition, scope, core_ideas, semantic_description, keywords_synonyms, sustainability_principle, principle_origin, underlying_mechanism, derived_from_practice_or_system, evidence_status, implementation_maturity, transferability, boundary_conditions, recommendation_trigger, status) VALUES ('SCR_0051', 'Reversibility and Safe-to-Fail Design', 'SYSTEMS; ECOLOGY; FUTURE_GENERATIONS', 'Resilience Engineering; Risk; Infrastructure; Design', 'When uncertainty is material, sustainability can be improved by preferring interventions that can be monitored, corrected, modified, or withdrawn before failures become irreversible, and by designing systems so that localized failure does not produce catastrophic consequences.', 'Applies where uncertainty, novelty, long system lifetimes, or asymmetric consequences make prediction difficult. Reversibility is not always possible or optimal; safety, cost, performance, and ecological consequences must be assessed, and safe-to-fail does not mean accepting preventable harm.', 'Prefer reversible commitments when justified; stage investments; monitor early signals; limit failure propagation; enable shutdown or correction; test recovery pathways; distinguish safe-to-fail from failure by design.', 'Reducing the consequence and irreversibility of errors can improve decision robustness when uncertainty cannot be eliminated.', 'reversibility;; safe-to-fail; design', 'Reducing the consequence and irreversibility of errors can improve decision robustness when uncertainty cannot be eliminated.', 'Engineering-Derived; Risk-Principle-Derived', 'Reversibility; staged deployment; containment; graceful failure; monitoring; recovery.', 'Pilot projects; staged infrastructure deployment; modular systems; floodable or sacrificial design elements; fail-safe controls; reversible land-use or technology decisions under uncertainty.', 'Established evidence base', 'Emerging/Established design approach', 'Infrastructure; technology; environmental management; policy', 'The approach is most relevant where uncertainty or consequence severity justifies retaining options. Reversibility may be impossible for some ecological, social, or infrastructure decisions; local failure containment must not substitute for adequate safety and prevention.', 'Candidate discovery when the application context contains evidence that reversibility and safe-to-fail design materially affects the sustainability outcome; validate the mechanism, scope, boundary conditions, and evidence before ranking.', 'Active'), ('SCR_0052', 'Just Transition', 'LIFE; PEOPLE; SYSTEMS; FUTURE_GENERATIONS', 'Labour; Energy Transition; Public Policy; Economics', 'Just transition requires that shifts toward environmentally sustainable systems protect human dignity, livelihoods, participation, social protection, and fair access to emerging opportunities, while addressing the uneven costs of structural change.', 'Applies where decarbonization, automation, resource restrictions, industrial restructuring, environmental regulation, or other sustainability transitions materially affect workers, communities, firms, or regions. It does not require preserving every existing job or technology; it requires fair management of transition impacts and opportunities.', 'Anticipate distributional effects; support affected workers and communities; enable reskilling and alternative livelihoods; involve affected actors in transition design; protect essential services; distribute new opportunities fairly.', 'Environmental and technological transitions change economic and social structures; sustainability requires managing the human consequences of that change rather than treating them as externalities.', 'just; transition', 'Environmental and technological transitions change economic and social structures; sustainability requires managing the human consequences of that change rather than treating them as externalities.', 'Policy-Derived; Human-Wellbeing-Derived', 'Reskilling; social protection; worker participation; regional transition; livelihood diversification.', 'Industrial decarbonization; coal and fossil-fuel transition; automation-related workforce change; regional economic transition; reskilling; social-protection and worker-support measures.', 'Established evidence base', 'Established policy principle', 'Energy; labour; industry; public policy; regional development', 'The affected workers, communities, sectors, time horizon, distribution of costs and benefits, and available transition measures must be identified. A transition cannot be called just solely because the end-state has lower environmental impact.', 'Candidate discovery when the application context contains evidence that just transition materially affects the sustainability outcome; validate the mechanism, scope, boundary conditions, and evidence before ranking.', 'Active'), ('SCR_0053', 'Universal Accessibility and Inclusive Design', 'LIFE; PEOPLE; SYSTEMS', 'Design; Infrastructure; Human Factors; Technology', 'Universal accessibility and inclusive design seek to make environments, products, services, information, and systems usable by people with diverse physical, sensory, cognitive, linguistic, and situational capabilities without requiring avoidable special adaptation.', 'Applies to physical infrastructure, digital systems, transport, education, public services, workplaces, and technologies where exclusion or additional barriers can materially affect participation or wellbeing. Universal design does not eliminate the need for individualized accommodations where required.', 'Design for diverse users from the outset; remove avoidable barriers; provide multiple interaction modes where justified; test with affected users; preserve dignity and autonomy; distinguish accessibility from convenience.', 'Design choices determine who can access and effectively use a system; inclusive design can expand capability while reducing dependence on after-the-fact adaptation.', 'universal; accessibility;; inclusive; design', 'Design choices determine who can access and effectively use a system; inclusive design can expand capability while reducing dependence on after-the-fact adaptation.', 'Human-Wellbeing-Derived; Design-Derived', 'Accessibility; universal design; assistive technology; inclusive interface; usability.', 'Accessible buildings and public spaces; inclusive transport; assistive technologies; accessible digital services; universal product and interface design; accommodation of diverse user capabilities.', 'Established evidence base', 'Established', 'Architecture; engineering; ICT; education; public services', 'Accessibility requirements depend on users, environments, tasks, standards, and foreseeable temporary or permanent limitations. Universal design may not eliminate the need for individualized accommodation, assistive technology, or specialized services.', 'Candidate discovery when the application context contains evidence that universal accessibility and inclusive design materially affects the sustainability outcome; validate the mechanism, scope, boundary conditions, and evidence before ranking.', 'Active'), ('SCR_0054', 'Transparency and Accountability', 'PEOPLE; SYSTEMS', 'Governance; Public Policy; AI; Organizations', 'Transparency and accountability require that relevant decisions, responsibilities, assumptions, evidence, performance, and avenues for review are sufficiently visible and attributable for affected parties to understand, question, and challenge consequential actions.', 'Applies to public institutions, organizations, infrastructure management, sustainability reporting, algorithmic systems, and resource allocation where decisions materially affect people or environmental outcomes. Transparency should be proportionate and must be balanced with legitimate privacy, security, confidentiality, and safety requirements.', 'Make responsibilities identifiable; disclose material assumptions and evidence; enable audit and review; provide reasons for consequential decisions; track outcomes; establish corrective mechanisms; avoid disclosure that creates disproportionate privacy or security risk.', 'Accountability mechanisms connect decisions and actions to identifiable responsibilities, evidence, review, and corrective action. Distinguishing emphasis: transparency is coupled with answerability, responsibility, or accountability for performance or decisions.', 'transparency;; accountability', 'Accountability mechanisms connect decisions and actions to identifiable responsibilities, evidence, review, and corrective action.', 'Governance-Derived; Legal-Doctrine-Derived', 'Auditability; explainability; reporting; oversight; grievance mechanisms; responsibility.', 'Environmental reporting; public project appraisal; procurement records; impact-assessment disclosure; sustainability performance reporting; auditable institutional decision processes.', 'Established evidence base', 'Established', 'Governance; public policy; AI; sustainability reporting', 'Information must be sufficiently complete, understandable, timely, and attributable to support scrutiny and correction. Privacy, security, confidentiality, and intellectual-property constraints may legitimately limit disclosure, but they do not remove the need for accountable decision-making.', 'Candidate discovery when the application context contains evidence that transparency and accountability materially affects the sustainability outcome; validate the mechanism, scope, boundary conditions, and evidence before ranking.', 'Active'), ('SCR_0055', 'Local Capacity and Maintainability', 'PEOPLE; SYSTEMS; ECOLOGY', 'Infrastructure; Operations; Community Systems; Engineering', 'Sustainability is strengthened when the people, skills, institutions, tools, spare parts, information, and financial arrangements required to operate and maintain a system are realistically available at the scale where the system depends on them.', 'Applies to infrastructure, decentralized technologies, community-managed resources, digital systems, public services, and facilities whose performance depends on continuing operation and maintenance. Local capacity does not require that every capability be local; external support can be sustainable when it is reliable, affordable, and institutionally appropriate.', 'Design for maintainability; match technology to available capability; preserve manuals and technical knowledge; ensure spare-part and service pathways; train operators; budget lifecycle maintenance; test institutional continuity.', 'A system that cannot be operated, repaired, monitored, or governed with available capabilities may fail despite strong initial technical performance. Distinguishing emphasis: the central test is whether the local people, skills, tools, spare parts, finance, information, and institutions needed for operation and maintenance are realistically available.', 'local; capacity;; maintainability', 'A system that cannot be operated, repaired, monitored, or governed with available capabilities may fail despite strong initial technical performance.', 'Engineering-Derived; Community-Practice-Derived', 'Maintainability; local skills; operator capacity; spare parts; lifecycle support; institutional capacity.', 'Community-scale water and sanitation; decentralized energy; rural infrastructure; maintainable public assets; locally serviceable equipment; spare-parts and technician availability.', 'Established evidence base', 'Established', 'Infrastructure; water; energy; campuses; community systems; ICT', 'The required skills, tools, spare parts, financing, documentation, institutional authority, and supply routes must exist or be realistically developable. Local deployment is unsustainable if operation depends on unavailable specialist support or unreliable replacement chains.', 'Candidate discovery when the application context contains evidence that local capacity and maintainability materially affects the sustainability outcome; validate the mechanism, scope, boundary conditions, and evidence before ranking.', 'Active'), ('SCR_0056', 'Knowledge Continuity and Transfer', 'PEOPLE; SYSTEMS; FUTURE_GENERATIONS', 'Education; Organizations; Engineering; Traditional Knowledge', 'Knowledge continuity preserves the information, skills, practices, rationale, and institutional memory needed to understand, operate, maintain, adapt, or replace systems over time. Sustainability can be weakened when essential knowledge disappears even though physical assets remain.', 'Applies where system performance depends on tacit knowledge, specialized skills, historical records, maintenance procedures, local ecological knowledge, design rationale, or institutional memory. Preservation should include appropriate provenance, access controls, cultural rights, and mechanisms for updating obsolete knowledge.', 'Document critical knowledge; transfer tacit skills; preserve design rationale; maintain institutional memory; support intergenerational learning; distinguish preservation from uncritical replication; update knowledge as conditions change.', 'Continuity of capability depends partly on continuity of the knowledge required to operate, interpret, maintain, and adapt a system.', 'knowledge; continuity;; transfer', 'Continuity of capability depends partly on continuity of the knowledge required to operate, interpret, maintain, and adapt a system.', 'Human-Wellbeing-Derived; Historical-Practice-Derived; Education-Derived', 'Tacit knowledge; documentation; apprenticeship; institutional memory; knowledge transfer.', 'Operations manuals; maintenance records; apprenticeship and skill transfer; institutional memory; traditional knowledge documentation; handover procedures for long-lived infrastructure and systems.', 'Established evidence base', 'Established', 'Engineering; education; organizations; traditional knowledge; public services', 'The knowledge that is critical to operation, maintenance, adaptation, and replacement must be identified and preserved in usable form. Documentation alone is insufficient where practical skills, tacit knowledge, or institutional authority are essential.', 'Use SCR_0090 for knowledge/skill continuity recommendations; retain SCR_0056 only for historical traceability.', 'Deprecated — merged into SCR_0090'), ('SCR_0057', 'Interoperability for Sustainable Transition', 'SYSTEMS; FUTURE_GENERATIONS', 'ICT; Infrastructure; Engineering; Standards', 'Interoperability for sustainable transition is the capacity of systems, components, data, and institutions to exchange or use information and functions through compatible interfaces and standards, reducing unnecessary lock-in and enabling incremental change.', 'Applies where long-lived systems must interact with new technologies, organizations, data sources, or infrastructure. Interoperability should be based on relevant standards and real functional requirements; excessive compatibility can add complexity, security risk, or resource use.', 'Use open or well-supported interfaces where appropriate; preserve data portability; avoid unnecessary vendor or technology lock-in; separate stable interfaces from replaceable components; assess security and lifecycle complexity.', 'Compatible interfaces can allow parts of a system to be replaced or upgraded without discarding the entire system, preserving existing value and future options.', 'interoperability; for; sustainable; transition', 'Compatible interfaces can allow parts of a system to be replaced or upgraded without discarding the entire system, preserving existing value and future options.', 'Engineering-Derived; Contemporary-Practice-Derived', 'Open standards; APIs; modular interfaces; data portability; system compatibility.', 'Open technical standards; interoperable energy, water, building, and digital systems; modular equipment replacement; data exchange across organizations; avoidance of unnecessary technology lock-in.', 'Established evidence base', 'Established', 'ICT; infrastructure; manufacturing; smart campuses; cyber-physical systems', 'Interoperability requires compatible interfaces, data semantics, standards, or contractual arrangements that remain usable across relevant system changes. Open interfaces can introduce security, governance, or integration costs and do not by themselves guarantee longer system life.', 'Candidate discovery when the application context contains evidence that interoperability for sustainable transition materially affects the sustainability outcome; validate the mechanism, scope, boundary conditions, and evidence before ranking.', 'Active'), ('SCR_0058', 'Adaptive Modularity', 'SYSTEMS; FUTURE_GENERATIONS', 'Engineering Design; Architecture; Infrastructure; Technology', 'Adaptive modularity organizes systems into sufficiently separable components or functions so that parts can be modified, replaced, scaled, or reconfigured as conditions change without unnecessary replacement of the whole system.', 'Applies where uncertainty, maintenance, technological change, or variable demand makes future modification valuable. Modularity introduces interfaces, materials, and coordination requirements; excessive modularity can reduce efficiency or increase complexity.', 'Separate functions where justified; make interfaces explicit; replace or upgrade components independently; support phased capacity; design for inspection and repair; evaluate interface and coordination costs.', 'Modularity can preserve useful system value by allowing localized change instead of whole-system replacement.', 'adaptive; modularity', 'Modularity can preserve useful system value by allowing localized change instead of whole-system replacement.', 'Engineering-Derived; Design-Derived', 'Modularity; reconfiguration; component replacement; phased capacity; maintainability.', 'Modular buildings; replaceable infrastructure components; scalable energy and water systems; modular computing and manufacturing systems; staged upgrades instead of whole-system replacement.', 'Established evidence base', 'Established', 'Engineering; architecture; infrastructure; manufacturing; computing', 'Modules must have meaningful functional boundaries and feasible interfaces; excessive modularity can increase material use, cost, complexity, and failure points. Reconfiguration should provide a credible advantage over replacing the complete system.', 'Candidate discovery when the application context contains evidence that adaptive modularity materially affects the sustainability outcome; validate the mechanism, scope, boundary conditions, and evidence before ranking.', 'Active'), ('SCR_0059', 'Cumulative Impact Awareness', 'ECOLOGY; PEOPLE; SYSTEMS; FUTURE_GENERATIONS', 'Environmental Assessment; Planning; Ecology; Public Policy', 'Cumulative impact awareness recognizes that individually small interventions can interact across space or time and produce material combined effects on ecological systems, communities, resources, or infrastructure.', 'Applies where multiple projects, activities, pollutants, withdrawals, land-use changes, or social pressures affect overlapping receptors or system capacities. Cumulative assessment requires attention to interaction, timing, spatial scale, baseline condition, and other reasonably attributable contributors.', 'Consider multiple pressures; define shared receptors and system capacities; account for temporal accumulation; identify interaction effects; avoid evaluating projects only in isolation; distinguish cumulative effects from unrelated background variation.', 'System response can depend on the combined load and sequence of multiple interventions rather than on the effect of any one intervention considered independently.', 'cumulative; impact; awareness', 'System response can depend on the combined load and sequence of multiple interventions rather than on the effect of any one intervention considered independently.', 'Scientific-Knowledge-Derived; Policy-Derived', 'Cumulative effects; carrying capacity; multiple stressors; combined exposure; spatial interaction.', 'Cumulative environmental assessment; watershed and airshed planning; multiple-project impact assessment; urban growth analysis; repeated extraction or disturbance over time.', 'Established evidence base', 'Established', 'Environmental assessment; urban planning; water; climate; infrastructure', 'Assessment must define spatial and temporal boundaries, interacting stressors, relevant receptors, and a credible baseline. Small individual effects should not be assumed cumulative without evidence of interaction or aggregation.', 'Candidate discovery when the application context contains evidence that cumulative impact awareness materially affects the sustainability outcome; validate the mechanism, scope, boundary conditions, and evidence before ranking.', 'Active'), ('SCR_0060', 'Ecological Regeneration and Restoration', 'ECOLOGY; FUTURE_GENERATIONS', 'Ecological Restoration; Conservation; Landscape Management', 'Ecological regeneration and restoration focus on recovering ecological structure, processes, functions, or trajectories after degradation, disturbance, or loss, while recognizing that restoration may produce a functioning future state rather than recreate an exact historical condition.', 'Applies where ecological systems have been degraded and recovery is feasible and appropriate. Restoration goals should reflect reference conditions, current constraints, future climate, ecological trajectories, and social context; some systems may require protection rather than active restoration.', 'Protect remaining intact function; remove or reduce degradation drivers; restore ecological processes; set measurable recovery objectives; use native or ecologically appropriate components where justified; monitor recovery and adapt management.', 'Ecological condition can improve when the drivers of degradation are reduced and the processes required for recovery are restored or supported.', 'ecological; regeneration;; restoration', 'Ecological condition can improve when the drivers of degradation are reduced and the processes required for recovery are restored or supported.', 'Nature-Derived; Scientific-Knowledge-Derived; Contemporary-Practice-Derived', 'Restoration; regeneration; recovery trajectory; habitat rehabilitation; ecological function.', 'Wetland restoration; forest and mangrove recovery; river and habitat rehabilitation; soil restoration; mine-site reclamation; assisted natural regeneration.', 'Established evidence base', 'Established', 'Ecology; watershed management; agriculture; urban restoration; conservation', 'The desired ecological functions, reference conditions, degradation mechanisms, and recovery trajectory must be defined. Restoration may produce a different but functioning ecosystem rather than reproduce a historical state, and recovery can be limited by irreversible thresholds.', 'Candidate discovery when the application context contains evidence that ecological regeneration and restoration materially affects the sustainability outcome; validate the mechanism, scope, boundary conditions, and evidence before ranking.', 'Active'), ('SCR_0061', 'Alternative Material Selection for Sustainability', 'SYSTEMS', 'Materials; Design; Circular Economy', 'Alternative material selection for sustainability is the deliberate comparison and selection of materials according to their functional performance together with their environmental, social, health, resource, and life-cycle implications. It treats material choice as a sustainability decision rather than only a technical or economic selection, while recognizing that the preferred material depends on the intended service, durability, maintenance, end-of-life pathway, availability, and consequences across the life cycle.', 'Applies wherever two or more materials can satisfy the required function and their life-cycle consequences differ. Assessment may consider embodied energy and emissions, resource criticality, toxicity, durability, repairability, recyclability or reuse potential, local availability, manufacturing requirements, maintenance, and end-of-life. A material is not sustainable merely because it is renewable, recycled, natural, or locally available; functional adequacy and whole-life consequences must remain part of the decision.', 'Compare materials on function and life-cycle consequences; avoid single-attribute selection; consider durability and maintenance; account for material scarcity and toxicity; evaluate end-of-life pathways; include context-specific environmental and social effects; prefer evidence-based multi-criteria selection.', 'Sustainability-oriented material choice should satisfy the required function while reducing significant life-cycle burdens and preserving future material options. Distinguishing emphasis: the decision variable is material choice or substitution based on life-cycle sustainability consequences.', 'Alternative material selection; sustainable materials; material substitution; life-cycle material choice', 'Sustainability-oriented material choice should satisfy the required function while reducing significant life-cycle burdens and preserving future material options.', 'Life-Cycle; Resource Stewardship; Circularity', 'Material properties and material supply chains determine resource use, embodied impacts, service life, maintenance needs, and recovery possibilities.', 'Material-selection decisions in buildings, infrastructure, manufacturing, packaging, products, and equipment where competing materials provide similar functions but differ in embodied impacts, toxicity, durability, scarcity, recyclability, or supply risk.', 'Established', 'Established', 'High', 'Material alternatives must first satisfy the required function, safety, durability, regulatory, and performance criteria. Environmental comparison should use a consistent functional basis and account for extraction, processing, transport, use, maintenance, and end-of-life effects where material.', 'Candidate when a decision includes alternative materials, material substitution, life-cycle assessment, embodied impacts, durability, toxicity, scarcity, or end-of-life considerations.', 'Active'), ('SCR_0062', 'Material Efficiency', 'SYSTEMS', 'Materials; Resource Efficiency; Circular Economy', 'Material efficiency is the provision of a required function or service with reduced use of virgin material and reduced material loss, while maintaining required performance, safety, durability, and service quality. It concerns both reducing material demand and increasing the useful service obtained from materials already extracted.', 'Applies to products, buildings, infrastructure, manufacturing, packaging, and other systems where material inputs can be reduced through efficient design, lightweighting, durability, reuse, repair, remanufacture, higher utilization, or improved process yield. Material efficiency must not be interpreted as simply minimizing mass when doing so shortens service life, increases failure risk, or shifts burdens elsewhere.', 'Provide more service from less material; reduce avoidable material loss; design for durability and high utilization; retain material value; distinguish mass reduction from whole-life efficiency; evaluate rebound and burden-shifting effects.', 'Material efficiency seeks to reduce virgin material demand and losses per unit of useful service delivered.', 'material efficiency; dematerialization; material productivity; resource efficiency', 'Material efficiency seeks to reduce virgin material demand and losses per unit of useful service delivered.', 'Resource Efficiency; Life-Cycle; Circular Economy', 'Design, manufacturing, use, and recovery decisions influence the amount of material required per unit of service and the duration for which that material remains useful.', 'Lightweight structural design; material yield improvement; near-net-shape manufacturing; waste-reducing fabrication; dimensional optimization; reduced material intensity per unit of service.', 'Established', 'Established', 'High', 'Reduced material quantity is beneficial only when required performance, safety, durability, repairability, and service life are maintained. Lightweighting or yield improvement can shift burdens to energy use, maintenance, replacement frequency, or difficult-to-recycle material combinations.', 'Candidate when material quantities, yield losses, lightweighting, resource productivity, or service-per-material comparisons are present.', 'Active'), ('SCR_0063', 'Design for Sustainability', 'SYSTEMS', 'Design; Engineering; Product Development; Infrastructure', 'Design for sustainability is the deliberate incorporation of environmental, social, economic, and long-term system considerations into design decisions so that a product, service, building, infrastructure system, or technology meets its intended function with reduced life-cycle burdens and improved resilience, usability, and future adaptability.', 'Applies from problem definition and requirements engineering through concept generation, material and process selection, detailed design, deployment, use, maintenance, and end-of-life. It is broader than environmental design alone and does not prescribe one design method; the relevant sustainability criteria depend on the system, users, life cycle, context, and evidence available.', 'Define the function before optimizing the artifact; consider the full life cycle; avoid burden shifting; design for durability, repair, reuse, recovery, and adaptation where relevant; include human needs and safety; test sustainability criteria alongside conventional performance requirements.', 'Sustainability should be treated as a design requirement affecting the specification, architecture, materials, operation, maintenance, and end-of-life of a system. Distinguishing emphasis: sustainability requirements are integrated into the broader design process across functions, materials, manufacture, use, maintenance, and end-of-life rather than being limited to material substitution.', 'design for sustainability; sustainable design; eco-design; life-cycle design', 'Sustainability should be treated as a design requirement affecting the specification, architecture, materials, operation, maintenance, and end-of-life of a system.', 'Life-Cycle; Design; Systems Thinking', 'Design choices establish many downstream resource, maintenance, use-phase, safety, and end-of-life consequences.', 'Sustainable product development; building and infrastructure design; service-system design; engineering design reviews; design requirements that include energy, material, environmental, social, maintenance, and end-of-life considerations.', 'Established', 'Established', 'High', 'The design boundary must include the functions and life-cycle stages materially affected by design choices. Sustainability criteria should not override mandatory safety, accessibility, performance, legal, or user requirements, and trade-offs must remain explicit.', 'Candidate when a design or development decision can influence life-cycle environmental, social, resource, safety, or adaptability outcomes.', 'Active'), ('SCR_0064', 'Design for Repair and Maintenance', 'SYSTEMS', 'Design; Asset Management; Circular Economy', 'Design for repair and maintenance is the principle of making products, equipment, buildings, and infrastructure capable of being inspected, serviced, repaired, maintained, and restored with reasonable access, information, tools, skills, time, and replacement components. It treats maintainability as a design property that can extend useful life and preserve function.', 'Applies where continued service depends on periodic inspection, servicing, component replacement, fault correction, or restoration. It includes accessibility, standardization, diagnostic information, replaceable components, maintenance procedures, and availability of parts or skills. It does not imply that every component should be repairable regardless of safety, contamination, cost, or technical feasibility.', 'Provide access to maintainable components; enable diagnosis; use replaceable or serviceable parts where appropriate; preserve maintenance information; support safe repair; consider local repair capability; evaluate maintenance burden over the life cycle.', 'Systems designed for repair and maintenance can retain useful function longer and reduce premature replacement and associated resource demand. Distinguishing emphasis: the primary mechanism is a design property that makes inspection, servicing, repair, and maintenance practicable; actual maintenance activity is not required at the design stage.', 'repairability; maintainability; serviceability; preventive maintenance; right to repair', 'Systems designed for repair and maintenance can retain useful function longer and reduce premature replacement and associated resource demand.', 'Circularity; Long-Life Use; Asset Stewardship', 'Physical architecture, component accessibility, diagnostics, spare-part availability, and maintenance capability determine whether repair can practically extend service life.', 'Replaceable wear parts; access panels; standard fasteners; diagnostic access; maintenance clearances; service documentation; maintainable buildings, machinery, electronics, infrastructure, and public assets.', 'Established', 'Established', 'High', 'Repairability depends on access, diagnostic information, compatible parts, tools, skills, safety, and reasonable repair time and cost. Repair is not preferable when the asset has an unsafe failure mode, severe degradation, obsolete functionality, or a replacement with substantially lower total impact is demonstrably available.', 'Candidate when repair, servicing, inspection, maintenance access, spare parts, diagnostics, or service-life extension are relevant.', 'Active'), ('SCR_0065', 'Design for Disassembly and Recovery', 'SYSTEMS', 'Design; Circular Economy; Manufacturing; Construction', 'Design for disassembly and recovery is the principle of configuring products, assemblies, buildings, and infrastructure so that components and materials can be separated at end of use or during major maintenance with feasible effort, damage, contamination control, and identification, enabling reuse, refurbishment, remanufacture, or material recovery.', 'Applies where components or materials have residual value after an initial service period. Relevant considerations include accessible connections, reversible joining where appropriate, material identification, separation of incompatible materials, modular assemblies, and recovery pathways. Disassembly should not compromise required structural integrity, safety, durability, or operational performance.', 'Preserve separability; identify materials and components; favor reversible connections where appropriate; reduce contamination; enable component recovery; design recovery pathways before deployment; balance recovery against safety and performance.', 'Products and built systems should preserve the possibility of recovering useful components and materials rather than making recovery unnecessarily difficult.', 'design for disassembly; design for recovery; deconstruction; material recovery', 'Products and built systems should preserve the possibility of recovering useful components and materials rather than making recovery unnecessarily difficult.', 'Circularity; Design; Residual Resource Value', 'Connection methods, material combinations, identification, contamination, and access determine the technical feasibility and cost of recovery.', 'Reversible joints; material separation; component identification; modular assemblies; selective demolition; design for component recovery and recycling at maintenance or end-of-life.', 'Established', 'Established', 'Moderate-High', 'Disassembly must be technically feasible at the relevant maintenance or end-of-life stage and should preserve component or material value. Fastener choice, adhesives, contamination, mixed materials, access, labour, safety, and available recovery infrastructure can determine whether the design actually enables recovery.', 'Candidate when products, structures, assemblies, or equipment may be disassembled for component reuse, refurbishment, remanufacture, or material recovery.', 'Active'), ('SCR_0066', 'Reuse Before Replacement', 'SYSTEMS', 'Circular Economy; Resource Management; Product Systems', 'Reuse before replacement is the sustainability principle that an existing product, component, material, structure, or asset should be considered for continued use in its current or adapted form before new production or disposal is selected, when reuse can meet functional, safety, health, and regulatory requirements.', 'Applies to products, components, building materials, equipment, packaging, infrastructure elements, and other assets with remaining functional value. Reuse may involve direct reuse, adaptation, relocation, or repurposing. It is not automatically preferable when inspection reveals unsafe degradation, contamination, excessive adaptation requirements, or a demonstrably greater whole-life burden.', 'Check existing assets before procuring new ones; assess remaining function; inspect and certify safety; adapt where justified; preserve component value; compare reuse against replacement using whole-life evidence; avoid premature disposal.', 'Retaining and reusing an existing functional asset can avoid the resource extraction, manufacturing, transport, and waste associated with producing a replacement.', 'reuse; direct reuse; adaptive reuse; reuse before replacement; asset retention', 'Retaining and reusing an existing functional asset can avoid the resource extraction, manufacturing, transport, and waste associated with producing a replacement.', 'Residual Resource Value; Long-Life Use; Functional Sufficiency', 'Reuse preserves an existing stock of embodied material and function, reducing the need for additional production when the existing asset remains suitable.', 'Reuse of buildings and structures; second-life equipment; component reuse; reclaimed construction materials; reuse of containers and packaging; adaptation of existing assets instead of unnecessary new production.', 'Established', 'Established', 'High', 'Reuse should be considered when the existing item can safely deliver the required function, directly or after proportionate adaptation. Reuse can be inappropriate when condition, contamination, regulatory requirements, performance, or life-cycle impacts make continued use unreasonable.', 'Candidate when an existing asset, component, product, structure, or material could satisfy a need before new procurement or replacement.', 'Active'), ('SCR_0067', 'Refurbishment and Remanufacturing', 'SYSTEMS', 'Circular Economy; Manufacturing; Asset Management', 'Refurbishment and remanufacturing preserve and restore the value of used products or components by inspecting, repairing, replacing, upgrading, or requalifying them for continued service. The principle recognizes that retaining an existing product or component can preserve material, manufacturing effort, and embedded function compared with producing an equivalent new item.', 'Applies where used products or components can be safely recovered and returned to an acceptable functional state. Refurbishment may involve partial restoration, while remanufacturing generally involves a controlled process intended to return a product or component to specified performance. Neither should be treated as preferable without considering energy, transport, testing, reliability, safety, and market or regulatory requirements.', 'Recover useful products and components; diagnose remaining value; restore function safely; replace only what is necessary; retain embodied materials and manufacturing effort; verify performance after restoration; compare restoration with new production on a whole-life basis.', 'Restoring used products or components can retain a greater share of their embodied material and functional value than discarding them and manufacturing replacements.', 'refurbishment; remanufacturing; restoration; product life extension', 'Restoring used products or components can retain a greater share of their embodied material and functional value than discarding them and manufacturing replacements.', 'Reuse Before Replacement; Residual Resource Value; Life-Cycle Responsibility', 'Inspection, repair, component replacement, testing, and requalification determine whether used assets can be returned to reliable service.', 'Industrial remanufacturing; equipment refurbishment; engine and machine rebuilding; electronics refurbishment; building-system renewal; requalification of used components for continued service.', 'Established', 'Established', 'Moderate-High', 'The used product or component must have sufficient residual technical value and a feasible route for inspection, disassembly, repair, replacement, testing, and requalification. Energy, replacement-part requirements, warranty, safety, and resulting service life must be considered.', 'Candidate when used products or components can be restored, upgraded, requalified, or returned to service instead of being discarded.', 'Active'), ('SCR_0068', 'Cascading Use of Materials', 'SYSTEMS; ECOLOGY', 'Circular Economy; Biomass; Materials', 'Cascading use of materials is the principle of directing a material or biomass resource through successive uses that preserve useful value before final disposal or irreversible degradation, particularly when different applications can extract different levels of functional value from the same resource.', 'Applies where a material can serve multiple sequential functions and where the sequence reduces virgin resource demand or disposal. The appropriate cascade depends on material properties, contamination, energy requirements, competing uses, and recovery infrastructure. Cascading should not be used to justify additional extraction merely because eventual reuse is possible.', 'Retain material function through successive uses; prioritize higher-value uses where justified; delay irreversible disposal; manage contamination; compare cascading pathways with direct recycling, recovery, or ecological return; account for energy and transport requirements.', 'Materials with remaining functional value should, where feasible, be directed through successive uses before their value is finally lost.', 'cascading use; cascade principle; biomass cascade; sequential use', 'Materials with remaining functional value should, where feasible, be directed through successive uses before their value is finally lost.', 'Material Circular Cycling; Residual Resource Value; Resource Regeneration Capacity', 'Material properties and quality degrade or change across use cycles, determining which subsequent applications remain feasible.', 'Sequential use of wood, biomass, fibres, plastics, metals, nutrients, or other materials in applications that progressively extract value before final disposal or irreversible degradation.', 'Established', 'Established', 'Moderate-High', 'Successive uses should retain material value and avoid creating hazardous or technically unrecoverable residues. The sequence depends on material quality, contamination, market or process demand, transport, processing energy, and the feasibility of recovery at each stage.', 'Candidate when materials or biomass can provide successive useful functions before recycling, recovery, disposal, or ecological return.', 'Active'), ('SCR_0069', 'Waste Prevention at Source', 'SYSTEMS', 'Waste Management; Resource Efficiency; Circular Economy', 'Waste prevention at source is the principle of avoiding the generation of waste before it occurs by reducing unnecessary material inputs, losses, defects, overproduction, packaging, hazardous substances, and other activities that create waste requiring subsequent treatment or disposal.', 'Applies across product design, manufacturing, construction, procurement, food systems, laboratories, offices, and service delivery. Prevention is distinct from recycling or treatment because it acts before waste is generated. Measures must not merely transfer waste to another medium or increase other environmental or social burdens.', 'Prevent generation before treatment; identify process losses; reduce defects and overproduction; avoid unnecessary packaging and material use; design processes around yield and demand; distinguish prevention from downstream waste management.', 'The most direct way to reduce waste burden is to avoid generating unnecessary waste at the source.', 'waste prevention; source reduction; waste minimization; prevention hierarchy', 'The most direct way to reduce waste burden is to avoid generating unnecessary waste at the source.', 'Loss Prevention Before Supply Expansion; Material Efficiency; Functional Sufficiency', 'Process design, demand, material selection, quality control, and operating practices determine how much waste is generated before recovery or disposal.', 'Process-yield improvement; defect reduction; right-sizing; overproduction control; packaging reduction; inventory-loss prevention; cleaner production; elimination of avoidable material inputs.', 'Established', 'Established', 'High', 'Prevention must address the process or decision that generates the waste rather than merely improve downstream treatment. Reducing waste must not transfer environmental burdens to product failure, unsafe operation, excessive resource use, or hidden waste elsewhere.', 'Candidate when the problem involves avoidable waste, defects, overproduction, unnecessary packaging, process losses, or upstream waste prevention.', 'Active'), ('SCR_0070', 'By-product and Industrial Symbiosis', 'SYSTEMS', 'Industry; Circular Economy; Resource Management', 'By-product and industrial symbiosis is the principle of treating outputs from one process that have usable value as potential inputs to another process, where technically, economically, environmentally, and legally feasible. It seeks to replace some virgin inputs and reduce disposal by coordinating material, energy, water, or other resource exchanges among processes or organizations.', 'Applies where one process produces a consistent and suitable secondary output and another process has a compatible input requirement. Feasibility depends on quantity, quality, timing, location, contamination, safety, regulation, infrastructure, and transaction costs. Not every waste stream is a suitable secondary resource.', 'Identify compatible input-output relationships; characterize quality and contamination; coordinate timing and logistics; verify regulatory and safety requirements; assess substitution of virgin inputs; evaluate the whole network rather than isolated exchanges.', 'Resource outputs that retain usable function can become inputs to another process, reducing both virgin resource demand and disposal requirements. Distinguishing emphasis: a real cross-process exchange is required in which a by-product or secondary resource substitutes for another process input under compatibility constraints.', 'industrial symbiosis; by-product exchange; resource exchange; industrial ecology', 'Resource outputs that retain usable function can become inputs to another process, reducing both virgin resource demand and disposal requirements.', 'Cross-Boundary Resource Exchange; Residual Resource Value; Material Circular Cycling', 'Material and energy flows between organizations create opportunities for substitution when output quality, quantity, timing, and infrastructure are compatible.', 'Exchange of heat, water, materials, by-products, or other process outputs between facilities or operations where one process output can satisfy another process input requirement.', 'Established', 'Established', 'Moderate-High', 'A proposed exchange requires compatible quantity, quality, timing, location, process requirements, contamination limits, safety, regulation, infrastructure, and economic feasibility. A nominal by-product is not a usable secondary resource without a real receiving use.', 'Candidate when one process produces a by-product or secondary resource that could substitute for another process input.', 'Active'), ('SCR_0071', 'Sustainable Procurement and Supplier Responsibility', 'SYSTEMS; PEOPLE', 'Procurement; Governance; Supply Chains', 'Sustainable procurement and supplier responsible management is the principle of incorporating environmental, social, ethical, life-cycle, and resilience considerations into purchasing and supplier-management decisions rather than evaluating suppliers solely on initial price, specification compliance, or delivery.', 'Applies to public and private procurement of materials, products, services, construction, equipment, and digital infrastructure. Criteria should be proportionate to the purchase and supported by evidence. Procurement requirements should not impose unverifiable claims, create unjustified barriers for smaller suppliers, or ignore safety, performance, affordability, and legal obligations.', 'Define sustainability criteria before procurement; consider whole-life value; assess supplier practices and risks; verify claims; include durability, repair, resource and social criteria where relevant; monitor supplier performance; avoid lowest-price-only decisions when they create greater whole-life cost or burden.', 'Purchasing decisions influence what is produced, how it is produced, and which environmental and social practices are rewarded across supply chains.', 'sustainable procurement; responsible sourcing; supplier responsible management; green procurement', 'Purchasing decisions influence what is produced, how it is produced, and which environmental and social practices are rewarded across supply chains.', 'Life-Cycle Responsibility; Transparency and Accountability; Responsibility for Environmental Burdens', 'Procurement specifications, supplier selection, contract conditions, verification, and performance monitoring transmit sustainability requirements through value chains.', 'Procurement specifications; supplier evaluation; environmental and social criteria in tenders; life-cycle requirements; traceability; supplier performance monitoring; responsible sourcing requirements.', 'Established', 'Established', 'Moderate-High', 'Criteria should be material to the purchase, proportionate to risk, verifiable, and compatible with legal, technical, safety, affordability, and competition requirements. Supplier claims require appropriate evidence, and responsibility should reflect the buyer’s actual influence over the supply chain.', 'Candidate when purchasing or supplier selection can incorporate life-cycle, environmental, social, ethical, durability, or resource criteria.', 'Active'), ('SCR_0072', 'Preventive Maintenance and Asset Life Extension', 'SYSTEMS', 'Asset Management; Infrastructure; Operations', 'Preventive maintenance and asset life extension is the principle of maintaining assets proactively according to condition, risk, operating requirements, or appropriate maintenance intervals so that function, safety, reliability, and service life are preserved and avoidable premature replacement is reduced.', 'Applies to infrastructure, machinery, buildings, vehicles, energy systems, water systems, digital infrastructure, and other assets where deterioration can be monitored or managed. Maintenance should be risk- and condition-informed rather than indiscriminately scheduled; excessive maintenance can also consume resources without corresponding benefit.', 'Maintain before failure where justified; inspect condition; prioritize high-consequence deterioration; preserve critical components; use maintenance data; distinguish preventive from corrective maintenance; evaluate maintenance resource use against avoided failures and replacement.', 'Timely maintenance can preserve existing assets, reduce failure and replacement demand, and maintain service with fewer additional material and energy inputs. Distinguishing emphasis: the sustainability mechanism is proactive maintenance based on condition, risk, or intervals to preserve safety, reliability, and service life; it is distinct from designing an asset to be repairable.', 'preventive maintenance; predictive maintenance; asset life extension; condition-based maintenance', 'Timely maintenance can preserve existing assets, reduce failure and replacement demand, and maintain service with fewer additional material and energy inputs.', 'Design for Repair and Maintenance; Long-Life Use; Local Capacity and Maintainability', 'Deterioration mechanisms, inspection, condition monitoring, maintenance intervals, and repair capability determine whether service life can be safely extended.', 'Condition monitoring; scheduled inspection; lubrication and servicing; preventive replacement of failure-prone parts; rehabilitation; calibration; maintenance planning for buildings, equipment, utilities, vehicles, and digital infrastructure.', 'Established', 'Established', 'Moderate-High', 'Maintenance intervals and interventions should be based on failure modes, condition, risk, operating environment, manufacturer requirements, or other credible evidence. Excessive maintenance can waste resources, while insufficient maintenance can shorten life or create safety and reliability risks.', 'Candidate when asset condition, maintenance intervals, failure risk, deterioration, or premature replacement are relevant.', 'Active'), ('SCR_0073', 'Demand Management Before Capacity Expansion', 'SYSTEMS', 'Resource Management; Infrastructure; Energy; Water', 'Demand management before capacity expansion is the principle of first examining whether avoidable or inefficient demand can be reduced, shifted, or better managed before increasing supply or physical capacity. It treats demand as a variable that can often be influenced through efficiency, behaviour, scheduling, pricing, design, or operational measures.', 'Applies to water, energy, transport, buildings, computing, telecommunications, infrastructure, and other systems where capacity expansion has material, financial, ecological, or social consequences. Demand reduction is not automatically preferable where it compromises essential services, health, dignity, safety, or equitable access.', 'Measure demand before forecasting expansion; identify avoidable demand; improve efficiency; shift flexible demand; protect essential access; compare demand-side and supply-side options using whole-life impacts and equity considerations.', 'When additional capacity has significant resource or environmental consequences, reducing avoidable demand can provide the required service with lower expansion pressure. Distinguishing emphasis: the primary intervention is broader demand-side reduction, efficiency, scheduling, shifting, pricing, behaviour, or service management before capacity expansion; loss reduction may be one component but is not the whole concept.', 'demand management; demand-side management; efficiency before expansion; capacity avoidance', 'When additional capacity has significant resource or environmental consequences, reducing avoidable demand can provide the required service with lower expansion pressure.', 'Loss Prevention Before Supply Expansion; Functional Sufficiency; Demand Flexibility and Load Shifting', 'Demand patterns, efficiency, user behaviour, system losses, scheduling, and service requirements determine whether demand-side measures can defer or reduce capacity expansion.', 'Water-demand management before new supply; energy-efficiency measures before generation expansion; transport-demand management before road expansion; building-load reduction before HVAC capacity increase; computing optimization before adding infrastructure.', 'Established', 'Established', 'High', 'Demand measures should be evaluated against service requirements, rebound effects, equity, reliability, and feasibility. Capacity expansion remains appropriate when demand cannot reasonably be reduced or when expansion is required for safety, health, resilience, or equitable access.', 'Candidate when additional capacity is being considered and demand reduction, efficiency, load shifting, or loss reduction could defer expansion.', 'Active'), ('SCR_0074', 'Resource Allocation by Need and Impact', 'PEOPLE; SYSTEMS', 'Management; Public Policy; Resource Governance', 'Resource allocation by need and impact is the principle of allocating scarce resources using explicit consideration of need, expected benefit, risk, distributional effects, and sustainability consequences rather than relying solely on aggregate demand, purchasing power, historical allocation, or convenience.', 'Applies to public services, infrastructure investment, budgets, water, energy, health-related resources, education, emergency response, and organizational resource allocation. Criteria must be transparent and context-specific. Equity does not necessarily require identical allocation; it may require differentiated allocation to address unequal needs or exposure.', 'Make allocation criteria explicit; identify essential needs; compare expected impacts; account for unequal burdens and benefits; protect vulnerable groups; disclose trade-offs; review allocation as evidence changes.', 'Sustainable resource allocation should account for who needs a resource, who bears the consequences, and what outcomes the allocation is expected to produce. Distinguishing emphasis: applies to allocation of any scarce resource, service, budget, or infrastructure using explicit need, benefit, risk, or distributional-impact criteria.', 'equitable allocation; needs-based allocation; impact-based allocation; resource governance', 'Sustainable resource allocation should account for who needs a resource, who bears the consequences, and what outcomes the allocation is expected to produce.', 'Equitable Sustainability; Human Capability and Dignity; Transparency and Accountability', 'Allocation rules determine the distribution of scarce resources, benefits, risks, and opportunities across people and places.', 'Public-budget allocation; water allocation during scarcity; energy and infrastructure investment; emergency-resource prioritization; service allocation based on need, expected benefit, risk, and distributional consequences.', 'Established', 'Established', 'Moderate-High', 'Allocation criteria must be explicit and relevant to the decision, with attention to unequal need, vulnerability, expected benefit, risk, and distributional effects. The principle does not prescribe equal shares and does not justify opaque or discriminatory allocation.', 'Candidate when scarce resources, services, budgets, or infrastructure must be allocated among users or locations with differing needs, risks, or impacts.', 'Active'), ('SCR_0075', 'Whole-Life Cost and Value Assessment', 'SYSTEMS', 'Economics; Engineering Management; Procurement', 'Whole-life cost and value assessment is the principle of evaluating alternatives over their relevant life cycle rather than comparing only initial acquisition cost. It considers costs and benefits associated with acquisition, operation, energy and resource use, maintenance, downtime, repair, replacement, residual value, and end-of-life, together with material sustainability consequences where appropriate.', 'Applies to investment, procurement, design, infrastructure, equipment, buildings, and service decisions with significant operating or end-of-life consequences. It does not reduce sustainability to monetary valuation; environmental and social effects may require separate metrics or multi-criteria assessment when they cannot be credibly monetized.', 'Look beyond purchase price; include operating and maintenance costs; account for replacement and residual value; compare alternatives over a consistent period; test uncertainty; keep monetary and non-monetary sustainability criteria explicit.', 'An alternative with a higher initial cost may provide greater long-term value and lower resource burden when operating, maintenance, replacement, and end-of-life consequences are considered.', 'life-cycle costing; whole-life cost; total cost of ownership; life-cycle value', 'An alternative with a higher initial cost may provide greater long-term value and lower resource burden when operating, maintenance, replacement, and end-of-life consequences are considered.', 'Metric-Aware Optimization; Life-Cycle Responsibility; Alternative Material Selection for Sustainability', 'Life-cycle cost, service life, operating requirements, maintenance, failure, replacement, and residual value influence the total value delivered by an option.', 'Capital investment appraisal; procurement of equipment and infrastructure; building alternatives; maintenance strategy selection; asset replacement decisions; comparison of alternatives using acquisition, operation, maintenance, and end-of-life consequences.', 'Established', 'Established', 'Moderate-High', 'Alternatives must be compared over a consistent analysis period and functional basis, including relevant capital, operating, maintenance, replacement, and end-of-life effects. Monetary valuation should not be used to conceal environmental or social effects that cannot be credibly monetized.', 'Candidate when alternatives differ in initial cost, operating cost, maintenance, service life, replacement, residual value, or end-of-life consequences.', 'Active'), ('SCR_0076', 'Environmental Cost Internalization', 'SYSTEMS; ECOLOGY', 'Environmental Economics; Policy; Governance', 'Environmental cost internalization is the principle of incorporating significant environmental externalities into decisions, prices, investment criteria, or regulatory mechanisms so that activities causing environmental damage face incentives or requirements reflecting at least part of those broader social and ecological costs.', 'Applies to policy, taxation, regulation, infrastructure appraisal, corporate decisions, and market design where environmental externalities can be reasonably characterized. Internalization mechanisms require careful boundary definition and should not be interpreted as permission to cause harm simply because a monetary value can be assigned.', 'Identify external costs; characterize affected systems and populations; use appropriate economic or regulatory instruments; avoid double counting; account for uncertainty and non-monetizable values; combine internalization with standards and limits where necessary.', 'Environmental decisions should not systematically ignore costs imposed on people or ecosystems outside the immediate transaction or organization.', 'externality internalization; environmental externalities; environmental pricing; social cost', 'Environmental decisions should not systematically ignore costs imposed on people or ecosystems outside the immediate transaction or organization.', 'Responsibility for Environmental Burdens; Polluter Pays Responsibility; Burden Transfer', 'Environmental impacts create costs or losses that may fall on parties other than the decision-maker; policy instruments can alter incentives by assigning responsibility for those consequences.', 'Environmental taxes and charges; emissions pricing; waste fees; resource-use charges; environmental provisions in investment appraisal; regulatory mechanisms that incorporate otherwise external environmental costs.', 'Established', 'Established', 'Moderate-High', 'The externality must be sufficiently characterized for the chosen instrument, including who bears the cost and which environmental effect is being represented. A price or charge is not equivalent to permission to pollute, and poorly designed charges can create distributional or leakage effects.', 'Candidate when an environmental externality or unpriced ecological/social cost materially affects a decision, policy, or investment.', 'Active'), ('SCR_0077', 'Polluter Pays Responsibility', 'SYSTEMS; PEOPLE; ECOLOGY', 'Environmental Governance; Law; Economics', 'Polluter pays responsibility is the principle that the party responsible for causing pollution or environmental damage should bear appropriate costs associated with preventing, controlling, managing, and, where legally required, remedying that damage rather than shifting those costs to the public or unaffected parties.', 'Applies within legal and policy systems where responsibility can be established and the relevant costs can be identified. It does not mean that payment makes environmental harm acceptable; prevention, standards, liability, restoration, and enforcement remain necessary. Attribution can be difficult for diffuse, cumulative, historical, or transboundary pollution.', 'Place responsibility with the source where practicable; prevent pollution first; recover appropriate prevention and remediation costs; maintain accountability; avoid cost shifting; recognize limits of attribution and cumulative causation.', 'Those who cause environmental pollution should bear appropriate responsibility for its prevention and consequences rather than systematically transferring the burden to others. Distinguishing emphasis: the responsible actor causing pollution or damage bears prevention, control, remediation, or compensation costs; generic accountability alone is insufficient.', 'polluter pays; environmental liability; cost responsibility; environmental accountability', 'Those who cause environmental pollution should bear appropriate responsibility for its prevention and consequences rather than systematically transferring the burden to others.', 'Responsibility for Environmental Burdens; Environmental Cost Internalization; Burden Transfer', 'Liability, regulation, attribution, monitoring, and enforcement determine how environmental responsibility is assigned and costs recovered.', 'Pollution-control liability; remediation requirements; environmental compensation; waste-management responsibility; regulatory enforcement; allocation of pollution-control costs to responsible actors where causation can be established.', 'Established', 'Established', 'Moderate-High', 'The responsible party and relevant burden must be established with defensible evidence or legal rules. The principle does not make pollution acceptable after payment and is difficult to apply mechanically to diffuse, historical, cumulative, or transboundary pollution.', 'Candidate when responsibility for pollution, environmental damage, prevention, control, or remediation must be assigned.', 'Active'), ('SCR_0078', 'Extended Producer Responsibility', 'SYSTEMS; PEOPLE', 'Circular Economy; Product Policy; Governance', 'Extended producer responsibility is the principle that producers can retain responsibility for specified environmental impacts of products beyond the point of sale, particularly through take-back, collection, recovery, treatment, information, or financing arrangements at the post-consumer stage, where established by policy or other appropriate mechanisms.', 'Applies to product systems where producer influence over design, materials, packaging, collection, or end-of-life can improve outcomes. The exact responsibilities depend on legal and institutional arrangements. EPR should be designed to create effective incentives without obscuring the responsibilities of consumers, waste operators, governments, or other actors.', 'Extend responsibility across the product life cycle; create incentives for better design; support collection and recovery; make responsibilities transparent; track outcomes; prevent cost and risk shifting to informal or vulnerable workers; align obligations with actual producer influence.', 'Product design and market decisions influence post-use impacts, so responsibility can extend beyond the point of sale to improve recovery and reduce waste burdens.', 'extended producer responsibility; EPR; producer take-back; product responsible management', 'Product design and market decisions influence post-use impacts, so responsibility can extend beyond the point of sale to improve recovery and reduce waste burdens.', 'Life-Cycle Responsibility; Responsibility for Environmental Burdens; Design for Disassembly and Recovery', 'Producer decisions influence material selection, product durability, recovery pathways, and the feasibility of post-consumer management.', 'Product take-back; packaging recovery; battery and electronic-waste systems; producer-financed collection and treatment; design incentives linked to end-of-life management.', 'Established', 'Established', 'Moderate-High', 'Producer obligations must be clearly defined within the applicable legal and institutional system and coordinated with consumers, waste operators, governments, and other actors. Responsibility should create credible incentives for better design and end-of-life outcomes without assuming producers control every downstream condition.', 'Candidate when producer influence over product design, take-back, collection, recovery, or post-consumer management is relevant.', 'Active'), ('SCR_0079', 'Monitoring, Feedback, and Corrective Action', 'SYSTEMS', 'Management; Environmental Management; Control', 'Monitoring, feedback, and corrective action is the principle of using measured evidence about system performance to identify deviation, deterioration, unintended consequences, or emerging risk and then adjusting actions, operations, or controls accordingly.', 'Applies to environmental management, infrastructure, resource systems, organizations, projects, and adaptive decision-making where relevant indicators can be measured with sufficient reliability. Monitoring is not valuable merely because data are collected; indicators must be connected to decisions, thresholds, responsibilities, and corrective actions.', 'Measure what matters; establish baselines; detect deviation; define response thresholds; assign responsibility; correct and learn; verify whether interventions worked; avoid collecting data without a decision pathway.', 'Sustainability management requires feedback from observed performance so that decisions can be corrected when outcomes diverge from intended conditions.', 'monitoring and evaluation; feedback control; corrective action; performance monitoring', 'Sustainability management requires feedback from observed performance so that decisions can be corrected when outcomes diverge from intended conditions.', 'Metric-Aware Optimization; Adaptive Learning; Adaptive Management Under Uncertainty', 'Measurement provides feedback about actual system state, enabling comparison with objectives and triggering corrective or adaptive action.', 'Environmental monitoring programmes; infrastructure condition monitoring; energy and water dashboards; project performance reviews; threshold-based intervention; corrective maintenance and management response.', 'Established', 'Established', 'High', 'Indicators must be relevant, measurable with adequate reliability, and connected to thresholds, decisions, responsible actors, and corrective measures. Data collection without a defined response pathway does not constitute effective feedback control.', 'Candidate when measured performance can be compared with objectives, thresholds, or baselines and used to trigger corrective action.', 'Active'), ('SCR_0080', 'Adaptive Management Under Uncertainty', 'SYSTEMS; ECOLOGY; FUTURE_GENERATIONS', 'Resilience; Governance; Environmental Management', 'Adaptive management under uncertainty is the principle of treating sustainability interventions as revisable decisions in systems where knowledge is incomplete, conditions change, or outcomes cannot be predicted with high confidence. Actions are designed so that monitoring and learning can improve subsequent decisions while avoiding unacceptable irreversible harm.', 'Applies to ecological management, climate adaptation, infrastructure planning, resource governance, and other long-horizon decisions with uncertainty. It requires meaningful feedback and decision flexibility; it is not an excuse for indefinite experimentation where risks are severe or where established protective action is already justified.', 'State uncertainty explicitly; choose informative interventions where safe; monitor outcomes; define adaptation triggers; preserve decision flexibility; distinguish reversible experimentation from irreversible commitment; combine learning with precaution.', 'Under uncertainty, sustainability decisions should preserve the ability to learn and adjust while maintaining safeguards against unacceptable harm. Distinguishing emphasis: the intervention itself remains revisable because outcomes are uncertain; monitoring, review points, and allowable adjustments must be defined.', 'adaptive management; learning by doing; iterative management; uncertainty', 'Under uncertainty, sustainability decisions should preserve the ability to learn and adjust while maintaining safeguards against unacceptable harm.', 'Adaptive Learning; Precaution Under Irreversible Risk; Multi-Future Robustness', 'Uncertain system responses require observation and iterative adjustment rather than reliance on a single static forecast.', 'Iterative ecosystem management; climate-adaptation planning; staged infrastructure decisions; experimental management with monitoring; policy revision based on observed outcomes.', 'Established', 'Established', 'Moderate-High', 'The uncertainty, decision variables, monitoring signals, review points, and allowable adjustments must be specified. Adaptive management is inappropriate as a substitute for immediate protective action where risks are severe, irreversible, or already well established.', 'Candidate when system conditions or outcomes are uncertain and decisions can be monitored and adapted without unacceptable irreversible harm.', 'Active'), ('SCR_0081', 'Participation in Resource Governance', 'PEOPLE; SYSTEMS', 'Governance; Natural Resources; Community Management', 'Participation in resource governance is the principle that people and groups affected by decisions about shared resources should have meaningful opportunities to contribute relevant knowledge, express interests, deliberate trade-offs, and influence decisions through processes appropriate to the context.', 'Applies to water, land, forests, fisheries, urban services, infrastructure, community assets, and other resources with distributed impacts or local knowledge. Participation must be meaningful rather than symbolic; it does not require that every participant have equal technical expertise or that every preference be adopted.', 'Include affected stakeholders early; make information understandable; recognize local and experiential knowledge; disclose trade-offs; provide channels for influence and feedback; clarify decision authority; document how participation affected the outcome.', 'Resource decisions are more legitimate and potentially more effective when affected people can contribute knowledge and influence decisions that shape their resources and conditions. Distinguishing emphasis: the participation mechanism is specifically tied to governance, allocation, monitoring, or stewardship of a shared resource.', 'participatory governance; stakeholder participation; community resource management; co-governance', 'Resource decisions are more legitimate and potentially more effective when affected people can contribute knowledge and influence decisions that shape their resources and conditions.', 'Meaningful Participation; Shared Resource Stewardship; Mechanism-Based Traditional Knowledge', 'Governance processes connect resource decisions with local knowledge, interests, accountability, and collective action.', 'Community water allocation; watershed planning; land-use decisions; fisheries management; local infrastructure planning; participatory environmental assessment where affected groups possess relevant knowledge or interests.', 'Established', 'Established', 'Moderate-High', 'Participants should have a genuine opportunity to contribute relevant knowledge, identify impacts, deliberate alternatives, and influence decisions within a clearly defined decision process. Participation does not eliminate professional duties, legal constraints, or the need for technical evidence.', 'Candidate when communities or affected groups have relevant knowledge, interests, or rights in decisions concerning shared resources.', 'Active'), ('SCR_0082', 'Transparency for Sustainability Decisions', 'SYSTEMS; PEOPLE', 'Governance; Management; Reporting', 'Transparency for sustainability decisions is the principle of making material assumptions, criteria, evidence, trade-offs, uncertainties, and relevant decision information sufficiently accessible for affected or accountable parties to understand how a sustainability-related decision was reached.', 'Applies to public policy, infrastructure decisions, procurement, corporate sustainability, environmental assessment, resource allocation, and other consequential decisions. Transparency is not equivalent to disclosure of every piece of information; privacy, security, intellectual property, and legitimate confidentiality constraints may apply.', 'Disclose decision criteria; identify evidence sources; state assumptions and uncertainty; explain trade-offs; make material information accessible; distinguish fact from judgment; preserve an auditable decision record.', 'Trustworthy sustainability decisions require enough relevant information about evidence, criteria, assumptions, and trade-offs for decisions to be examined and understood. Distinguishing emphasis: information is made visible, interpretable, and decision-relevant so that sustainability choices can be evaluated; formal accountability is not required.', 'transparency; disclosure; traceability; decision transparency; open evidence', 'Trustworthy sustainability decisions require enough relevant information about evidence, criteria, assumptions, and trade-offs for decisions to be examined and understood.', 'Transparency and Accountability; Metric-Aware Optimization; Meaningful Participation', 'Transparency enables scrutiny, informed participation, accountability, and learning from sustainability decisions.', 'Disclosure of environmental assumptions; public reporting; accessible project information; procurement transparency; explanation of sustainability criteria; publication of monitoring results and decision rationales.', 'Established', 'Established', 'Moderate-High', 'The information disclosed should cover material assumptions, criteria, evidence, uncertainties, trade-offs, and decision responsibilities in a form that affected or accountable parties can understand. Disclosure must still respect legitimate privacy, security, and confidentiality constraints.', 'Candidate when sustainability decisions depend on explicit evidence, assumptions, criteria, uncertainty, trade-offs, or decision records.', 'Active'), ('SCR_0083', 'Accountability Across Value Chains', 'PEOPLE; SYSTEMS', 'Supply Chains; Governance; Corporate Responsibility', 'Accountability across value chains is the principle that sustainability responsibilities should be considered across the interconnected stages through which materials, products, services, information, risks, and impacts move, rather than assigning responsibility only to the organization or process at the point where an outcome becomes visible.', 'Applies to supply chains, infrastructure delivery, manufacturing, food systems, digital services, construction, and other distributed production systems. Accountability should reflect actual influence, responsibility, contractual arrangements, and causal contribution; it should not become an unsupported claim that one actor controls every upstream or downstream outcome.', 'Map relevant value-chain stages; identify material impacts and dependencies; assign responsibilities according to influence and contribution; verify supplier and contractor information; address risks beyond organizational boundaries; avoid responsibility shifting.', 'Sustainability impacts can arise outside organizational boundaries, so effective responsibility requires visibility and appropriate action across relevant value-chain stages.', 'value-chain accountability; supply-chain responsibility; due diligence; chain-of-custody', 'Sustainability impacts can arise outside organizational boundaries, so effective responsibility requires visibility and appropriate action across relevant value-chain stages.', 'Responsibility for Environmental Burdens; Sustainable Procurement and Supplier Stewardship; Transparency and Accountability', 'Value-chain structure distributes impacts, information, risks, and responsibilities among multiple actors.', 'Supply-chain due diligence; product traceability; construction-material sourcing; food-system impacts; electronics supply chains; contractor and supplier responsibility for material environmental and social risks.', 'Established', 'Established', 'Moderate-High', 'Responsibilities should follow actual influence, contractual duties, causal contribution, and available control at each relevant stage. Value-chain framing should not turn remote association into an unsupported claim of direct responsibility.', 'Candidate when environmental, social, or resource impacts arise across multiple organizations or stages of a value chain.', 'Active'), ('SCR_0084', 'Local and Context-Appropriate Provision', 'SYSTEMS; PEOPLE; ECOLOGY', 'Infrastructure; Technology; Development', 'Local and context-appropriate provision is the principle of selecting or designing technologies, services, infrastructure, and resource systems that fit local environmental conditions, available skills, maintenance capacity, institutions, affordability, cultural context, and actual user needs rather than assuming that a technically advanced solution is universally appropriate.', 'Applies to infrastructure, water and sanitation, energy, housing, agriculture, health-support systems, digital services, and community-scale technologies. Local does not automatically mean sustainable, and high-technology solutions may be appropriate where local capacity and life-cycle performance support them.', 'Match solution complexity to context; assess local skills and maintenance; consider affordability and access; use locally available resources where appropriate; involve users; test long-term operability; avoid technology transfer without institutional and environmental fit.', 'A solution is more likely to remain sustainable when its technical characteristics are compatible with the environmental, social, economic, and institutional conditions in which it must operate. Distinguishing emphasis: appropriateness is broader than ecological fit and includes skills, institutions, affordability, culture, maintenance, supply chains, and actual user needs.', 'context-appropriate technology; appropriate technology; local capacity; contextual fit', 'A solution is more likely to remain sustainable when its technical characteristics are compatible with the environmental, social, economic, and institutional conditions in which it must operate.', 'Local Ecological Fit; Local Capacity and Maintainability; Technology for Expanded Human and Ecological Options', 'Technology performance depends on environmental conditions, skills, institutions, supply chains, maintenance, affordability, and user practices.', 'Decentralized water and sanitation; local energy systems; climate-responsive buildings; locally serviceable infrastructure; community-scale technologies; technology choices matched to local environmental and institutional conditions.', 'Established', 'Established', 'Moderate-High', 'Suitability must be demonstrated against local environmental conditions, demand, skills, maintenance capacity, affordability, safety, regulation, and life-cycle performance. Local sourcing or small scale alone does not establish appropriateness.', 'Candidate when technology or service performance depends strongly on local environmental, institutional, skill, affordability, or cultural conditions.', 'Active'), ('SCR_0085', 'Affordability and Equitable Access', 'LIFE; PEOPLE; SYSTEMS', 'Social Sustainability; Public Services; Economics', 'Affordability and equitable access is the principle that essential goods, services, infrastructure, and opportunities should be accessible without imposing disproportionate financial or practical burdens on people, particularly where unequal access can undermine health, dignity, capability, participation, or livelihood.', 'Applies to water, sanitation, energy, housing, transport, education, digital access, health-related services, and other essential systems. Affordability must be assessed relative to income, household circumstances, geography, accessibility, and service quality; low price alone does not establish equitable access if quality or safety is inadequate.', 'Assess access as well as average cost; identify affordability barriers; protect essential service access; consider differentiated needs; examine geographic and disability-related barriers; evaluate who benefits and who bears costs.', 'Sustainability requires that essential services remain practically and financially accessible rather than improving aggregate system performance while excluding or burdening vulnerable users.', 'affordability; equitable access; service access; energy poverty; water affordability', 'Sustainability requires that essential services remain practically and financially accessible rather than improving aggregate system performance while excluding or burdening vulnerable users.', 'Equitable Sustainability; Human Capability and Dignity; Resource Allocation by Need and Impact', 'Prices, service design, distribution, infrastructure location, income, and institutional arrangements shape who can obtain and benefit from essential services.', 'Water and sanitation tariffs; energy access; public transport; housing; digital connectivity; essential services where price, geography, accessibility, and service quality affect actual access.', 'Established', 'Established', 'Moderate-High', 'Access should be assessed using total user burden, including price, connection or travel costs, time, accessibility, reliability, quality, and geographic constraints. Low monetary price is not sufficient if the service is unsafe, unreliable, or practically inaccessible.', 'Candidate when access to essential services or opportunities differs because of financial, geographic, physical, or social barriers.', 'Active'), ('SCR_0086', 'Safer Substitution and Hazard Reduction', 'PEOPLE; ECOLOGY; SYSTEMS', 'Materials; Chemical Safety; Product Design', 'Safer substitution and hazard reduction is the principle of replacing hazardous substances, processes, or design choices with less hazardous alternatives where technically feasible, while preventing exposure and reducing risks to workers, users, communities, and ecosystems across the life cycle.', 'Applies to chemicals, materials, manufacturing processes, products, laboratories, construction, agriculture, and waste management. Substitution must consider functional performance, toxicity, exposure pathways, persistence, degradation products, fire or physical hazards, and life-cycle consequences. A substitute should not be considered safer merely because one hazard is reduced if another significant hazard is introduced.', 'Eliminate hazards where feasible; substitute safer alternatives; assess exposure pathways; compare hazard profiles; prevent regrettable substitution; use controls where substitution is not feasible; consider workers, users, communities, and ecosystems.', 'Reducing hazard at the source can prevent harm more effectively than relying only on downstream exposure control or waste treatment.', 'safer substitution; hazard reduction; non-toxic materials; chemical substitution; pollution prevention', 'Reducing hazard at the source can prevent harm more effectively than relying only on downstream exposure control or waste treatment.', 'Preventive Sustainability; Alternative Material Selection for Sustainability; Responsibility for Environmental Burdens', 'Hazard properties, exposure pathways, process design, substitution options, and control measures determine risk to people and ecosystems.', 'Chemical substitution; safer construction materials; process redesign; replacement of hazardous solvents or substances; exposure reduction in laboratories, workplaces, agriculture, manufacturing, and waste handling.', 'Established', 'Established', 'Moderate-High', 'The substitute must satisfy the required function while reducing relevant hazard under realistic exposure conditions. Assessment should include toxicity, persistence, exposure pathways, degradation products, fire or physical hazards, worker and user exposure, and life-cycle consequences.', 'Candidate when hazardous substances, materials, processes, or exposure pathways can be reduced or replaced by safer alternatives.', 'Active'), ('SCR_0087', 'Sustainable Use Intensity', 'SYSTEMS; ECOLOGY', 'Resource Management; Infrastructure; Operations', 'Sustainable use intensity is the principle of evaluating the pressure placed on a resource, asset, ecosystem, or service relative to its capacity, condition, recovery, or intended function, rather than judging sustainability from total use alone.', 'Applies where the same aggregate consumption can produce different sustainability outcomes depending on local capacity, timing, concentration, duration, or system condition. Relevant measures may include withdrawal per renewable supply, occupancy relative to carrying capacity, load relative to infrastructure capacity, or resource use per service delivered.', 'Measure pressure relative to capacity; distinguish aggregate use from intensity; account for temporal and spatial concentration; monitor thresholds and recovery; avoid interpreting low intensity as sustainable when absolute limits are exceeded.', 'Sustainability depends on resource or system pressure relative to the capacity of the system to support, absorb, or recover from that pressure.', 'use intensity; resource pressure; carrying capacity; load intensity; withdrawal intensity', 'Sustainability depends on resource or system pressure relative to the capacity of the system to support, absorb, or recover from that pressure.', 'Ecological Limits; Resource Regeneration Capacity; Metric-Aware Optimization', 'Resource availability, system capacity, recovery rate, demand, and temporal or spatial concentration determine sustainable use intensity.', 'Water withdrawal relative to renewable availability; grazing or harvesting pressure relative to ecosystem capacity; occupancy relative to infrastructure or ecological limits; energy or material use per unit of delivered service.', 'Established', 'Established', 'Moderate-High', 'Intensity must be related to a meaningful capacity, condition, recovery rate, or service requirement. The appropriate denominator and threshold depend on the system, and lower intensity per unit does not guarantee lower total impact if total demand rises.', 'Candidate when sustainability depends on pressure or use relative to resource, ecological, infrastructure, or recovery capacity.', 'Active'), ('SCR_0088', 'Prevention Before Remediation', 'SYSTEMS; ECOLOGY; PEOPLE', 'Environmental Management; Risk Management; Public Health', 'Prevention before remediation is the principle of prioritizing measures that avoid the creation or escalation of environmental or social harm before relying on later corrective, treatment, restoration, or compensation measures.', 'Applies to pollution, waste, environmental degradation, infrastructure failure, occupational risk, public-health risks, and other situations where preventive measures can reduce downstream consequences. Prevention is not always sufficient; remediation remains necessary when harm has already occurred or prevention cannot eliminate residual risk.', 'Identify hazards upstream; remove or reduce causes; use preventive controls; monitor emerging impacts; intervene early; reserve remediation for residual or existing damage; compare prevention and remediation over the whole life cycle.', 'Avoiding harm at its source generally reduces the resources, exposure, uncertainty, and residual damage associated with correcting harm after it occurs. Distinguishing emphasis: use this concept when the decision is specifically between preventing a harmful release, degradation, or exposure and remediating it after occurrence.', 'prevention hierarchy; pollution prevention; prevention before remediation; upstream intervention', 'Avoiding harm at its source generally reduces the resources, exposure, uncertainty, and residual damage associated with correcting harm after it occurs.', 'Preventive Sustainability; Waste Prevention at Source; Precaution Under Irreversible Risk', 'Cause-oriented intervention reduces the probability or magnitude of downstream damage and remediation requirements.', 'Pollution prevention; leak prevention; preventive safety measures; source reduction; erosion control; failure prevention; waste avoidance before treatment, cleanup, restoration, or compensation.', 'Established', 'Established', 'Moderate-High', 'Prevention should address identifiable causes before harm occurs or escalates. Where harm already exists or cannot be fully prevented, remediation and residual-risk management remain necessary; prevention must not be used to avoid addressing existing damage.', 'Candidate when upstream prevention can avoid or reduce the need for downstream treatment, remediation, restoration, or compensation.', 'Active'), ('SCR_0089', 'Sustainable Capacity Utilization', 'SYSTEMS', 'Infrastructure; Operations; Economics', 'Sustainable capacity utilization is the principle of operating infrastructure, equipment, facilities, or other capacity at levels that deliver required service without persistent underutilization that wastes embodied resources or overutilization that accelerates deterioration, failure, congestion, or excessive energy and resource demand.', 'Applies to buildings, transport, utilities, manufacturing, computing infrastructure, laboratories, public facilities, and other capacity-constrained systems. The appropriate utilization range is system-specific and may vary over time. Maximizing utilization is not automatically sustainable when it compromises resilience, maintenance, safety, accessibility, or future flexibility.', 'Match capacity to actual service needs; identify persistent underuse; avoid chronic overload; consider shared use; schedule flexible demand; preserve safety margins; account for embodied capacity as well as operating efficiency.', 'Existing capacity should be used effectively where feasible before adding new capacity, while maintaining the margins required for safety, resilience, and future needs.', 'capacity utilization; asset utilization; shared capacity; infrastructure utilization', 'Existing capacity should be used effectively where feasible before adding new capacity, while maintaining the margins required for safety, resilience, and future needs.', 'Demand Management Before Capacity Expansion; Functional Sufficiency; Distributed Resilience', 'Utilization affects whether embodied capacity provides useful service and whether operation approaches limits that increase energy, wear, congestion, or failure risk.', 'Building occupancy; transport-network utilization; equipment loading; manufacturing capacity; data-centre utilization; laboratory and public-facility use where excessive underuse or overloading has resource or service consequences.', 'Established', 'Established', 'Moderate-High', 'The relevant operating range depends on reliability, maintenance, safety, accessibility, resilience, and service requirements. Maximizing utilization can be unsustainable if it accelerates deterioration, removes contingency capacity, or compromises future flexibility.', 'Candidate when existing capacity is persistently underused or chronically overloaded and utilization affects resource efficiency or service quality.', 'Active'), ('SCR_0090', 'Knowledge and Skill Continuity for Sustainability', 'PEOPLE; SYSTEMS; FUTURE_GENERATIONS', 'Knowledge Management; Operations; Community Capacity', 'Knowledge and skill continuity for sustainability is the principle of preserving and transferring the knowledge, skills, practices, records, and institutional memory required to operate, maintain, adapt, and govern systems over time, especially when sustainability outcomes depend on locally accumulated or specialized knowledge.', 'Applies to infrastructure operation, traditional ecological knowledge, community resource management, maintenance-intensive technologies, organizations, and long-lived projects. Continuity does not mean freezing practices; knowledge should remain open to verification, learning, adaptation, and integration with new evidence.', 'Document critical knowledge; support intergenerational and cross-role transfer; preserve tacit and procedural knowledge where possible; maintain training pathways; combine local experience with scientific evidence; update knowledge as conditions change.', 'Sustainability over long time horizons depends on retaining the capability to understand, operate, maintain, and adapt systems after individual people, technologies, or project teams change.', 'knowledge continuity; institutional memory; skill transfer; intergenerational knowledge', 'Sustainability over long time horizons depends on retaining the capability to understand, operate, maintain, and adapt systems after individual people, technologies, or project teams change.', 'Knowledge Continuity and Transfer; Local Capacity and Maintainability; Mechanism-Based Traditional Knowledge', 'Loss of operational or contextual knowledge can reduce maintenance quality, adaptive capacity, and continuity of sustainability practices.', 'Training and succession planning; operator certification; maintenance knowledge transfer; community technical capacity; documentation of critical procedures; continuity planning for long-lived infrastructure and organizations.', 'Established', 'Established', 'Moderate-High', 'Critical knowledge must remain available to the people and institutions responsible for operation, maintenance, adaptation, and governance. Continuity should support verification and updating rather than preserve practices unchanged when evidence or conditions require modification.', 'Candidate when long-term operation, maintenance, adaptation, or responsible management depends on retaining and transferring specialized, local, or institutional knowledge.', 'Active'), ('SCR_0091', 'Social Protection as Shock Buffer', 'LIFE; PEOPLE; SYSTEMS; FUTURE_GENERATIONS', 'Social resilience and public systems', 'Social protection as shock buffering is the sustainability principle of maintaining basic income, service access, or other essential support so that people facing shocks do not lose the capabilities and minimum conditions required for well-being and recovery.', 'Applies where economic, environmental, health, employment, or other shocks can push vulnerable people below a minimum level of security or access. It concerns protective systems that reduce exposure to severe welfare loss; it does not imply that all risks should be absorbed by public support or that support can substitute for structural risk reduction.', 'Protect minimum capabilities; reduce vulnerability to shocks; maintain access to essential services; prioritize people with greater exposure or lower coping capacity; combine immediate protection with longer-term resilience.', 'Links sustainability and resilience to mechanisms that prevent shocks from converting into persistent loss of basic capabilities.', 'social protection; social safety net; shock-responsive protection; vulnerability buffering; basic income support; resilience support', 'Sustainability should maintain essential human capabilities and access to basic services when foreseeable shocks threaten to push vulnerable populations below a minimum level of security.', 'Social-policy practice; resilience and development evidence', 'Transfers, services, insurance, or other protective measures reduce the immediate welfare loss caused by shocks, preserving health, livelihood, education, and recovery capacity.', 'Social protection floors; shock-responsive social assistance; livelihood support for vulnerable groups during economic or climate shocks.', 'Direct UN SDG target and action evidence', 'Established', 'Disaster resilience; public services; health; livelihoods; education; climate adaptation', 'Protection must reach people exposed to material shocks and be sufficient, timely, and administratively accessible. It should complement rather than replace prevention, risk reduction, or structural reforms.', 'Consider when an application context involves shocks, vulnerability, loss of basic services, or unequal capacity to absorb disruption.', 'Active'), ('SCR_0092', 'Nutrition-Sensitive Local Provision', 'LIFE; PEOPLE; ECOLOGY; SYSTEMS', 'Food systems and human well-being', 'Nutrition-sensitive local provision is the sustainability principle of designing food-production and provisioning systems so that local availability, livelihood conditions, production diversity, and nutritional quality are considered together rather than treating food volume or income as sufficient outcomes.', 'Applies to food systems where production and provisioning choices affect dietary quality, household livelihoods, and local resource conditions. It does not require all food to be locally produced, and local production is not inherently sustainable if it degrades resources or reduces nutritional diversity.', 'Link production with nutrition; diversify where it improves dietary quality and resilience; consider producer livelihoods; connect food security with resource sustainability; evaluate outcomes beyond production volume.', 'Connects food-system sustainability to the joint consideration of nutritional outcomes, local production capability, livelihoods, and resource conditions.', 'nutrition-sensitive agriculture; nutrition-sensitive food systems; diversified local production; food and nutrition security', 'Sustainable food systems should evaluate production choices by their contribution to nutritional adequacy, livelihood security, and long-term resource conditions together.', 'Food-system practice; public-health and agricultural development evidence', 'Diversified and context-appropriate production can improve availability of nutrient-rich foods while supporting producer livelihoods and reducing dependence on narrowly optimized production pathways.', 'Diversified sustainable agricultural production systems linked to child nutrition and producer livelihoods; Farmer Field Schools promoting agroecological production.', 'Direct UN SDG action evidence', 'Established', 'Agriculture; food systems; public health; rural development; procurement', 'Local production should be evaluated for nutritional value, ecological impacts, affordability, seasonality, and livelihood effects; localization alone is not evidence of sustainability.', 'Consider when a technical or social application affects food production, provisioning, nutrition, agricultural livelihoods, or resource-intensive food systems.', 'Active'), ('SCR_0093', 'Gender-Responsive Resource Access', 'PEOPLE; SYSTEMS', 'Equity and resource governance', 'Gender-responsive resource access is the sustainability principle of assessing and addressing gender-specific barriers to access, control, ownership, safety, participation, and benefit-sharing when resources, services, infrastructure, technology, or opportunities are allocated or designed.', 'Applies where gender roles, legal arrangements, social norms, care responsibilities, safety conditions, or unequal control over resources can alter actual access or outcomes. It does not mean assuming identical needs or prescribing a single gender-specific solution across contexts.', 'Assess differential access; distinguish formal availability from effective access and control; account for safety and care constraints; include affected groups in decisions; evaluate distribution of benefits and burdens.', 'Extends equitable access from nominal availability to gender-differentiated access, control, participation, and outcomes.', 'gender-responsive access; gender-responsive design; gender equity in resources; women’s resource access; gender-sensitive planning', 'Sustainability decisions should account for gender-differentiated barriers and control over resources so that formal equality does not conceal unequal practical access or outcomes.', 'Gender-equality policy; inclusive development practice', 'Identifying and removing gender-specific barriers changes who can access, control, use, and benefit from resources and decisions.', 'Gender-responsive public services and infrastructure; women’s participation in resource governance; reforms addressing women’s land, financial, technological, and leadership access.', 'Direct UN SDG target and action evidence', 'Established', 'Infrastructure; water; land; finance; technology; education; governance; workplace systems', 'The relevant gender-related barriers must be evidenced or established in the application context. The principle should not be reduced to demographic labelling without identifying a mechanism affecting access or outcomes.', 'Consider when an application involves resource allocation, infrastructure access, technology adoption, land or financial rights, safety, or decision-making with gender-differentiated effects.', 'Active'), ('SCR_0094', 'Decent Work and Worker Well-Being', 'LIFE; PEOPLE; SYSTEMS; FUTURE_GENERATIONS', 'Work systems and economic sustainability', 'Decent work and worker well-being is the sustainability principle of designing economic and production systems so that productive activity is compatible with safe working conditions, fair treatment, human dignity, rights, and durable worker capability.', 'Applies to employment, production, service delivery, supply chains, and technology-mediated work where productivity choices can affect worker safety, health, security, or dignity. It does not equate sustainability with employment quantity alone.', 'Protect health and safety; preserve dignity and rights; maintain productive capability; consider working conditions alongside productivity; prevent shifting environmental or economic gains onto workers.', 'Connects economic sustainability with the conditions under which productive work is performed and the preservation of worker capability and dignity.', 'decent work; worker well-being; occupational safety; safe work; labour rights; sustainable employment', 'Economic activity is not sustainable when productivity or growth depends on unsafe, degrading, or rights-incompatible working conditions.', 'Labour standards; social sustainability; economic development practice', 'Safe and fair working conditions reduce harm, preserve human capability, improve continuity of productive activity, and prevent externalization of social costs onto workers.', 'Demand-driven skills and apprenticeship programmes; occupational inspection and labour-protection systems; decent-work initiatives.', 'Direct UN SDG action and target evidence', 'Established', 'Manufacturing; construction; services; agriculture; digital work; supply chains', 'Worker impacts must be material to the system being evaluated. Productivity gains should not be classified as sustainable if they depend on avoidable safety, health, rights, or dignity losses.', 'Consider when course concepts affect workplace design, automation, production systems, infrastructure construction, supply chains, or employment conditions.', 'Active'), ('SCR_0095', 'Policy Coherence for Sustainability', 'SYSTEMS; PEOPLE; ECOLOGY; FUTURE_GENERATIONS', 'Governance and systems integration', 'Policy coherence for sustainability is the sustainability principle of aligning policies, rules, incentives, plans, and implementation mechanisms across sectors and levels of governance so that actions supporting one objective do not systematically undermine another sustainability objective.', 'Applies where multiple policies, institutions, sectors, or governance levels influence the same sustainability outcome. It concerns interaction and consistency among policy instruments; it does not require all policies to have identical objectives or eliminate legitimate trade-offs.', 'Identify policy interactions; detect contradictions and adverse incentives; align objectives and implementation; manage trade-offs explicitly; coordinate across institutional boundaries and time horizons.', 'Treats sustainability as a cross-policy coordination problem in which contradictory incentives or fragmented governance can undermine otherwise beneficial interventions.', 'policy coherence; coherent sustainability policy; cross-sector policy alignment; policy integration; governance coherence', 'Sustainability outcomes improve when policies and institutional incentives are mutually coherent across sectors, scales, and time horizons, with unavoidable trade-offs made explicit.', 'Sustainable-development governance; policy-integration practice', 'Alignment reduces contradictory incentives, duplicated effort, policy leakage, and cross-sector displacement of environmental or social burdens.', 'Mechanisms for policy coherence for sustainable development; coordinated multi-sector implementation and planning under the 2030 Agenda.', 'Direct UN SDG target evidence', 'Established', 'Public policy; infrastructure planning; water-energy-food systems; climate policy; institutional strategy', 'Coherence must be assessed across the policies and institutions materially affecting the outcome. Alignment does not imply that conflicts disappear; significant trade-offs still require explicit decision-making.', 'Consider when an application spans multiple policies, departments, governance levels, regulations, incentives, or sustainability objectives.', 'Active'), ('SCR_0096', 'Shared Knowledge and Resource Mobilization', 'SYSTEMS; PEOPLE; FUTURE_GENERATIONS', 'Partnerships and implementation capacity', 'Shared knowledge and resource mobilization is the sustainability principle of deliberately combining complementary knowledge, expertise, technology, financial resources, and implementation capabilities across actors when no single actor can effectively address a sustainability challenge alone.', 'Applies to multi-actor problems requiring complementary capabilities, resources, or knowledge. Collaboration is not inherently sustainable: roles, incentives, accountability, power, data rights, and distribution of benefits must be considered.', 'Combine complementary capabilities; mobilize resources around a defined outcome; enable knowledge and technology exchange; clarify roles and accountability; retain local ownership and implementation capacity.', 'Frames partnership as a mechanism for overcoming capability and resource discontinuities in complex sustainability implementation.', 'knowledge mobilization; resource mobilization; capacity sharing; multi-stakeholder collaboration; knowledge exchange; implementation partnership', 'Complex sustainability challenges should mobilize and share complementary knowledge, expertise, technology, and resources across capable actors while maintaining clear roles, accountability, and local implementation capacity.', 'UN SDG partnership practice; development cooperation', 'Pooling complementary capabilities closes technical, financial, institutional, and knowledge gaps that can prevent otherwise feasible sustainability interventions from being implemented or scaled.', 'Multi-stakeholder SDG partnerships; technical and capacity-building collaborations; knowledge and technology sharing initiatives.', 'Direct UN SDG target evidence', 'Established', 'Research; education; infrastructure; public services; technology deployment; community development', 'Partnerships should address a real capability or resource gap and include mechanisms for accountability, knowledge transfer, and durable local capacity. Partnership formation alone is not evidence of sustainability.', 'Consider when a sustainability application requires complementary expertise, technology, finance, institutional capacity, or community knowledge from multiple actors.', 'Active') ON CONFLICT DO NOTHING;